(() => {
  const ID='neon-hook',tg=window.Telegram?.WebApp,shell=()=>window.TelePlayGameShell,$=id=>document.getElementById(id);
  let screen,canvas,renderer,engine,input,startLayer,resultLayer,selectedLevel=0,callbacks={},resultTimer=0,deathFxRaf=0,runToken=0;
  function haptic(type){try{tg?.HapticFeedback?.[type==='success'?'notificationOccurred':'impactOccurred'](type==='success'?'success':type)}catch(_) {}}
  const newRunToken=()=>`${Date.now()}-${Math.random().toString(36).slice(2,9)}`;
  function toast(text,color='#fff'){const el=$('hookEventToast');el.textContent=text;el.style.color=color;el.classList.remove('show');requestAnimationFrame(()=>el.classList.add('show'));clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),850)}
  function updateHud(s){if(!s)return;$('hookScore').textContent=Math.floor(s.score).toLocaleString('ru-RU');$('hookCombo').textContent=`×${s.combo}`;$('hookComboStat').classList.toggle('hot',s.combo>1);$('hookRunCoins').textContent=s.coins;$('hookLevelProgress').textContent=`LEVEL ${s.levelIndex+1}`;$('hookProgress').textContent=`${Math.floor(s.progress)}%`;$('hookProgressBar').style.width=`${s.progress}%`;}
  function renderLevelPicker(){const max=window.NeonHookConfig.maxLevel,stats=shell().getStats(ID),highest=Math.min(max,Math.max(1,stats.highestLevel||1));if(selectedLevel===0&&highest>1)selectedLevel=highest-1;selectedLevel=Math.min(selectedLevel,highest-1);$('hookLevelLabel').textContent=`УРОВЕНЬ ${selectedLevel+1} / ${max}`;$('hookLevelPrev').disabled=selectedLevel===0;$('hookLevelNext').disabled=selectedLevel>=highest-1;$('hookMenuBest').textContent=stats.bestScore?.toLocaleString('ru-RU')||'0';}
  function stopDeathFx(){if(deathFxRaf)cancelAnimationFrame(deathFxRaf);deathFxRaf=0}
  function animateDeath(snapshot){stopDeathFx();const until=performance.now()+260;const frame=()=>{renderer.render({...snapshot,state:'dead'},engine.level);if(performance.now()<until)deathFxRaf=requestAnimationFrame(frame);else deathFxRaf=0};deathFxRaf=requestAnimationFrame(frame)}
  function showResult(snapshot,completed){
    if(resultTimer)return;resultTimer=setTimeout(()=>{resultTimer=0;const previous=shell().getStats(ID),levelNumber=snapshot.levelIndex+1,completedLevels=Array.from(new Set([...(previous.completedLevels||[]),...(completed?[levelNumber]:[])] )).sort((a,b)=>a-b),highestLevel=Math.max(previous.highestLevel||1,completed?Math.min(window.NeonHookConfig.maxLevel,levelNumber+1):1),result=shell().saveResult(ID,Math.floor(snapshot.score),{bestLevel:Math.max(previous.bestLevel||0,completed?levelNumber:0),highestLevel,completedLevels,bestCombo:Math.max(previous.bestCombo||1,snapshot.maxCombo),coinsCollected:(previous.coinsCollected||0)+snapshot.coins,lastResult:{score:Math.floor(snapshot.score),level:levelNumber,progress:Math.floor(snapshot.progress),combo:snapshot.maxCombo,coins:snapshot.coins,completed}}),reward=snapshot.coins+(completed?5+snapshot.levelIndex:0),isRecord=result.newRecord;window.TelePlayCore.RewardManager.award(ID,{coins:reward,score:Math.floor(snapshot.score),metadata:{transactionId:`game:${ID}:run:${runToken}`,runToken,level:levelNumber}});shell().emit('neon_hook_finished',{gameId:ID,score:Math.floor(snapshot.score),level:levelNumber,progress:Math.floor(snapshot.progress),coins:snapshot.coins,reward,completed,maxCombo:snapshot.maxCombo});shell().emit('game_finished',{gameId:ID,score:Math.floor(snapshot.score),reward,maxCombo:snapshot.maxCombo,progress:Math.floor(snapshot.progress),completed,levelCompleted:completed,playTime:Math.floor(snapshot.elapsed||0)});shell().emit('reward_claimed',{gameId:ID,reward});if(isRecord){screen.classList.add('hook-record');shell().emit('neon_hook_new_record',{gameId:ID,score:Math.floor(snapshot.score),level:levelNumber});shell().emit('new_record',{gameId:ID,score:Math.floor(snapshot.score)});shell().SoundManager.play('record');haptic('success')}const nextButton=$('hookNext');nextButton.hidden=!completed||snapshot.levelIndex>=window.NeonHookConfig.maxLevel-1;nextButton.textContent=snapshot.levelIndex===window.NeonHookConfig.maxLevel-1?'Все уровни пройдены':'Следующий уровень';shell().ResultScreen.show(resultLayer,{score:Math.floor(snapshot.score),bestScore:result.bestScore,reward,newRecord:isRecord,title:completed?'Уровень<br>пройден!':'Ещё<br>попытка?',details:{level:`${levelNumber} / ${window.NeonHookConfig.maxLevel}`,distance:`${snapshot.distance} м`,hooks:snapshot.hooks,maxCombo:`×${snapshot.maxCombo}`}});resultLayer.hidden=false},completed?120:280)}
  function start(levelIndex=selectedLevel){if(resultTimer){clearTimeout(resultTimer);resultTimer=0}runToken=newRunToken();stopDeathFx();const stats=shell().getStats(ID),highest=Math.min(window.NeonHookConfig.maxLevel,Math.max(1,stats.highestLevel||1));selectedLevel=Math.max(0,Math.min(highest-1,levelIndex));startLayer.hidden=true;resultLayer.hidden=true;screen.classList.remove('hook-death','hook-record','hook-complete');input?.setEnabled(true);renderer.reset();engine.start(selectedLevel);shell().emit('neon_hook_started',{gameId:ID,level:selectedLevel+1});shell().emit('game_started',{gameId:ID});haptic('light')}
  function restart(){shell().emit('neon_hook_restart',{gameId:ID,level:selectedLevel+1});start(selectedLevel)}
  function open(options={}){callbacks=options;screen.hidden=false;startLayer.hidden=false;resultLayer.hidden=true;renderLevelPicker();renderer.resize();engine.reset(selectedLevel);renderer.render(engine.snapshot(),engine.level);try{tg?.requestFullscreen();tg?.disableVerticalSwipes()}catch(_) {}}
  function hide(){engine?.stop();input?.setEnabled(false);stopDeathFx();if(resultTimer){clearTimeout(resultTimer);resultTimer=0}if(screen)screen.hidden=true;try{tg?.enableVerticalSwipes();tg?.exitFullscreen()}catch(_) {}}
  function close(){hide();callbacks.onHome?.()}
  function init(){
    screen=$('neonHookScreen');canvas=$('neonHookCanvas');startLayer=$('neonHookStart');resultLayer=$('neonHookResult');renderer=new window.NeonHookRenderer(canvas,window.NeonHookConfig);engine=new window.NeonHookEngine(window.NeonHookConfig,{onFrame:s=>{renderer.render(s,engine.level);updateHud(s)},onHook:()=>{shell().SoundManager.play('hook');haptic('light');toast('HOOK ATTACHED','#a879ff')},onRelease:()=>{renderer.emit(112,300,'#5bf3ff',12);shell().SoundManager.play('release')},onPerfectRelease:e=>{renderer.emit(112,300,'#ffd66e',20);toast(`PERFECT RELEASE +${e.points}`,'#ffd66e');shell().SoundManager.play('perfectRelease');shell().emit('neon_hook_perfect_release',{gameId:ID,level:e.snapshot.levelIndex+1,combo:e.snapshot.combo});haptic('medium')},onCoin:e=>{renderer.emit(112,300,e.coin.risk==='risk'?'#ff5bc8':'#ffd66e',10);shell().SoundManager.play('coin');haptic('light');shell().emit('neon_hook_coin_collected',{gameId:ID,level:e.snapshot.levelIndex+1,risk:e.coin.risk,coins:e.snapshot.coins})},onDeath:({reason,snapshot})=>{screen.classList.add('hook-death');renderer.emit(112,300,'#ff5b8c',30);renderer.cameraShake=12;animateDeath(snapshot);shell().SoundManager.play('death');haptic('heavy');shell().emit('neon_hook_failed',{gameId:ID,level:snapshot.levelIndex+1,reason,progress:Math.floor(snapshot.progress)});showResult(snapshot,false)},onFinish:snapshot=>{screen.classList.add('hook-complete');renderer.emit(112,300,'#ffd66e',36);renderer.emit(112,300,'#5bf3ff',28);shell().SoundManager.play('levelComplete');haptic('success');showResult(snapshot,true)},onPause:()=>{$('hookPause').textContent='▶'},onResume:()=>{$('hookPause').textContent='Ⅱ'}});
    $('hookStartButton').addEventListener('click',()=>start(selectedLevel));$('hookReplay').addEventListener('click',restart);$('hookNext').addEventListener('click',()=>{selectedLevel=Math.min(window.NeonHookConfig.maxLevel-1,selectedLevel+1);start(selectedLevel)});$('hookHome').addEventListener('click',close);$('hookClose').addEventListener('click',close);$('hookPause').addEventListener('click',()=>engine.state==='paused'?engine.resume():engine.pause());$('hookLevelPrev').addEventListener('click',()=>{selectedLevel=Math.max(0,selectedLevel-1);renderLevelPicker()});$('hookLevelNext').addEventListener('click',()=>{selectedLevel=Math.min(window.NeonHookConfig.maxLevel-1,selectedLevel+1);renderLevelPicker()});
    input=new window.ArcadeInputManager(canvas,{onDown:()=>engine.pointerDown(),onUp:()=>engine.pointerUp(),onCancel:()=>engine.pointerUp()});input.setEnabled(false);window.addEventListener('resize',()=>renderer.resize());document.addEventListener('visibilitychange',()=>{if(document.hidden&&engine.state==='playing')engine.pause()});renderLevelPicker();
  }
  window.NeonHookGame={init,open,close,hide,start,restart,pause:()=>engine?.pause(),resume:()=>engine?.resume(),destroy:()=>engine?.destroy(),getEngine:()=>engine};
  document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init):init();
})();
